import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineDiscount, lineVat, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice creates a draft invoice with expanded line items', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-002');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 2);
  assert.deepEqual(r.value.lines[0], {
    sku: 'DES-HOUR',
    name: 'Design work (hour)',
    qty: 10,
    unitPrice: 8500,
    vatRate: 21,
    discountPercent: 0,
  });
});

test('createInvoice reports CUSTOMER_NOT_FOUND for an unknown customer', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }), { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice reports DATE_INVALID for invalid date formats', () => {
  const testCases = ['2026-10-7', '2026-1-07', '26-10-07', '10-07-2026', 'not-a-date', ''];
  for (const date of testCases) {
    assert.deepEqual(createInvoice({
      customerId: 'C-003',
      issueDate: date,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }), { ok: false, error: 'DATE_INVALID' }, `for date "${date}"`);
  }
});

test('createInvoice reports DATE_INVALID for impossible dates', () => {
  const testCases = ['2026-02-30', '2026-13-01', '2026-00-01', '2026-06-31'];
  for (const date of testCases) {
    assert.deepEqual(createInvoice({
      customerId: 'C-003',
      issueDate: date,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }), { ok: false, error: 'DATE_INVALID' }, `for date "${date}"`);
  }
});

test('createInvoice reports NO_LINES for an empty lines array', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [],
  }), { ok: false, error: 'NO_LINES' });
});

test('createInvoice reports NO_LINES for non-array lines', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: null,
  }), { ok: false, error: 'NO_LINES' });
});

test('createInvoice reports QTY_INVALID for non-integer quantities', () => {
  const testCases = [0, -1, 1.5, 'abc', null, undefined];
  for (const qty of testCases) {
    assert.deepEqual(createInvoice({
      customerId: 'C-003',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty }],
    }), { ok: false, error: 'QTY_INVALID' }, `for qty ${qty}`);
  }
});

test('createInvoice reports UNKNOWN_SKU for a SKU that is not in the catalogue', () => {
  assert.deepEqual(createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'NOPE', qty: 1 }],
  }), { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice does not mutate the input lines array', () => {
  const lines = [{ sku: 'DES-HOUR', qty: 1 }];
  createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines,
  });
  assert.deepEqual(lines, [{ sku: 'DES-HOUR', qty: 1 }]);
});

test('createInvoice stops at the first error', () => {
  const r = createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'NOPE', qty: 0 }],
  });
  assert.equal(r.error, 'CUSTOMER_NOT_FOUND');
});

test('lineTotal returns qty times unitPrice', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 8500 }), 8500);
  assert.equal(lineTotal({ qty: 10, unitPrice: 8500 }), 85000);
  assert.equal(lineTotal({ qty: 2, unitPrice: 50 }), 100);
  assert.equal(lineTotal({ qty: 100, unitPrice: 1 }), 100);
});

test('invoiceTotals calculates subtotal, discount, and total', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 8500, discountPercent: 0 },
      { qty: 5, unitPrice: 9500, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000 + 47500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, 85000 + 47500);
});

test('invoiceTotals handles a single line', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 12345, discountPercent: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 12345);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, 12345);
});

test('invoiceTotals returns zero for empty invoice', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals with a created invoice', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });
  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);
  assert.equal(totals.subtotal, 10 * 8500 + 5 * 9500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, 10 * 8500 + 5 * 9500);
});

test('createInvoice accepts discountPercent on lines', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10, discountPercent: 10 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 10);
});

test('createInvoice accepts decimal discountPercent values', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10, discountPercent: 12.5 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 12.5);
});

test('createInvoice reports DISCOUNT_INVALID for discountPercent outside 0-100', () => {
  const testCases = [-1, 101, 100.1, 'abc', null, undefined];
  for (const discountPercent of testCases) {
    const r = createInvoice({
      customerId: 'C-003',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent }],
    });
    // undefined should work (defaults to 0), so skip it
    if (discountPercent !== undefined) {
      assert.equal(r.ok, false, `should fail for discountPercent ${discountPercent}`);
      assert.equal(r.error, 'DISCOUNT_INVALID', `for discountPercent ${discountPercent}`);
    }
  }
});

test('createInvoice applies gold tier discount when discountPercent not provided', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 5);
});

test('createInvoice applies silver tier discount when discountPercent not provided', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 2.5);
});

test('createInvoice applies standard tier discount when discountPercent not provided', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 0);
});

test('createInvoice uses explicit discountPercent over tier discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10, discountPercent: 15 },
