test('renderInvoiceText shows correct total', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });
  assert.equal(r.ok, true);
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  // 10 * 8500 + 5 * 9500 = 85000 + 47500 = 132500 cents
  // VAT: round(85000 * 21/100) + round(47500 * 21/100) = 17850 + 9975 = 27825 cents
  // Total: 132500 + 27825 = 160325 cents = €1,603.25
  assert.equal(lines[4], 'VAT: €278.25');
  assert.equal(lines[5], 'Total: €1,603.25');
});

test('renderInvoiceText with single line invoice', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1000 }],
  });
  assert.equal(r.ok, true);
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  // number, name, 1 line, VAT, total
  assert.equal(lines.length, 5);
  assert.ok(lines[2].includes('Sticker sheet'));
  // Subtotal: 1000 * 50 = 50000 cents
  // VAT: round(50000 * 21/100) = 10500 cents = €105.00
  // Total: 50000 + 10500 = 60500 cents = €605.00
  assert.equal(lines[3], 'VAT: €105.00');
  assert.equal(lines[4], 'Total: €605.00');
});

