    issueDate: '2026-10-07',
    status: 'sent',
    lines: [{ sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };
  assert.deepEqual(addLine(invoice, { sku: 'DEV-HOUR', qty: 1 }), { ok: false, error: 'NOT_DRAFT' });
});

test('addLine reports QTY_INVALID for invalid quantities', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const testCases = [0, -1, 1.5, 'abc'];
  for (const qty of testCases) {
    assert.deepEqual(addLine(r1.value, { sku: 'DEV-HOUR', qty }), { ok: false, error: 'QTY_INVALID' }, `for qty ${qty}`);
  }
});

test('addLine reports UNKNOWN_SKU for unknown SKUs', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.deepEqual(addLine(r1.value, { sku: 'NOPE', qty: 1 }), { ok: false, error: 'UNKNOWN_SKU' });
});

test('addLine does not mutate the input invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const original = r1.value;
  const originalLineCount = original.lines.length;
  const originalQty = original.lines[0].qty;

  addLine(original, { sku: 'DEV-HOUR', qty: 3 });

  assert.equal(original.lines.length, originalLineCount);
  assert.equal(original.lines[0].qty, originalQty);
});

test('addLine accepts discountPercent for new lines', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = addLine(r1.value, { sku: 'DEV-HOUR', qty: 3, discountPercent: 15 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines[1].discountPercent, 15);
});

test('addLine accepts decimal discountPercent', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const r2 = addLine(r1.value, { sku: 'DEV-HOUR', qty: 3, discountPercent: 12.5 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines[1].discountPercent, 12.5);
});

test('addLine reports DISCOUNT_INVALID for invalid discountPercent', () => {
  const r1 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const testCases = [-1, 101, 100.1, 'abc', null];
  for (const discountPercent of testCases) {
    assert.deepEqual(addLine(r1.value, { sku: 'DEV-HOUR', qty: 1, discountPercent }), { ok: false, error: 'DISCOUNT_INVALID' }, `for discountPercent ${discountPercent}`);
  }
});

test('addLine defaults discountPercent to 0 when not provided', () => {
